stString	+= "* 53 EXPUNGE\r\n";			testString	+= "* 64 RECENT\r\n";			testString	+= "* 75 FETCH (FLAGS (\flag1 \flag2 \flag3 fubar))\r\n";			testString	+= "* NO This is a ÔNOÕ message.\r\n";			testString	+= "* BAD This is a ÔBADÕ message.\r\n";			testString	+= "* OK [ALERT] This is an ÔALERTÕ message.\r\n";			testString	+= testTag;			testString	+= " OK CAPABILITY completed\r\n";;						parseBuffer.append(testString.c_str(), testString.length());			// Create a capability parser and test it out.			CTextPtr parsePtr(&parseBuffer);			CCapabilityParse myParser(&parsePtr, testTag);			CCapabilityResponseToken* result = myParser.ParseCapabilityStream();#if qDebug			result->Dump(cout);#endif			delete	result;		}				// Build a psuedo LOGIN responsestream and fill it in.		{			cout << "\nTesting CLoginParse\n";			parseBuffer.reset();			string		testTag("A124");			string		testString;			testString	=  "* NO This is a ÔNOÕ message.\r\n";			testString	+= "* BAD This is a ÔBADÕ message.\r\n";			testString	+= "* OK [ALERT] This is an ÔALERTÕ message.\r\n";			testString	+= testTag;			testString	+= " OK LOGIN completed\r\n";						parseBuffer.append(testString.c_str(), testString.length());			// Create a Login parser and test it out.			CTextPtr parsePtr(&parseBuffer);			CLoginParse myParser(&parsePtr, testTag);			CLoginResponseToken* result = myParser.ParseLoginStream();#if qDebug			result->Dump(cout);#endif			delete	result;		}				// Build a psuedo LOGOUT responsestream and fill it in.		{			cout << "\nTesting CLogoutParse\n";			parseBuffer.reset();			string		testTag("A125");			string		testString;			testString	=  "* NO This is a ÔNOÕ message.\r\n";			testString	+= "* BAD This is a ÔBADÕ message.\r\n";			testString	+= "* BYE Autologout; idle for too long.\r\n";			testString	+= "* OK [ALERT] This is an ÔALERTÕ message.\r\n";			testString	+= testTag;			testString	+= " OK LOGOUT completed\r\n";						parseBuffer.append(testString.c_str(), testString.length());			// Create a Login parser and test it out.			CTextPtr parsePtr(&parseBuffer);			CLogoutParse myParser(&parsePtr, testTag);			CLogoutResponseToken* result = myParser.ParseLogoutStream();#if qDebug			result->Dump(cout);#endif			delete	result;		}		cout << "\nDone.\n";	}	catch (CException_AC& fi)	{#if qDebug		cout << "main: ACS exception: " << fi.GetError() << '\n';#endif	}	catch (exception& theException)	{#if qDebug		cout << "main: Exception: " << theException.what() << '\n';#endif	}	catch (...)	{#if qDebug		cout << "main: Unknown exception\n";#endif	}	cout << "Command-Q to quit.\n";}//----------------------------------------------------------------------------------------// End of Parser.cpp